CREATE TABLE research_sources (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), url TEXT NOT NULL, title TEXT NOT NULL, publisher TEXT NOT NULL, published_at TEXT, captured_at TEXT NOT NULL, acquisition TEXT NOT NULL CHECK(acquisition IN ('manual','url_import')), text TEXT NOT NULL, content_hash TEXT NOT NULL, duplicate_of TEXT REFERENCES research_sources(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), version INTEGER NOT NULL DEFAULT 1, withdrawn_reason TEXT, UNIQUE(project_id, url, content_hash));
CREATE INDEX research_sources_project_idx ON research_sources(project_id, captured_at);
CREATE TABLE research_claims (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), statement TEXT NOT NULL, fingerprint TEXT NOT NULL, event_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected','disputed')), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id, fingerprint));
CREATE INDEX research_claims_project_idx ON research_claims(project_id, status);
CREATE TABLE claim_evidence (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES research_claims(id), source_id TEXT NOT NULL REFERENCES research_sources(id), quote TEXT NOT NULL, quote_start INTEGER NOT NULL, quote_end INTEGER NOT NULL, relation TEXT NOT NULL CHECK(relation IN ('supports','contradicts','context')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), version INTEGER NOT NULL DEFAULT 1, withdrawn_reason TEXT, created_at TEXT NOT NULL, UNIQUE(claim_id, source_id, quote_start, quote_end, relation));
CREATE INDEX claim_evidence_claim_idx ON claim_evidence(claim_id);
CREATE TABLE claim_reviews (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES research_claims(id), reviewer_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN ('pending','verified','rejected','disputed')), reason TEXT NOT NULL, event TEXT NOT NULL, claim_version INTEGER NOT NULL, evidence_snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX claim_reviews_claim_idx ON claim_reviews(claim_id, claim_version);
CREATE TABLE source_events (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES research_sources(id), actor_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, reason TEXT NOT NULL, source_version INTEGER NOT NULL, metadata_snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX source_events_source_idx ON source_events(source_id, source_version);
